1	/**
2	 * 引擎公开错误类型。
3	 *
4	 * 设计约定：
5	 * - 提交阶段（普通交易 / 策略变更）对“内容不合法”的判定互不混用：
6	 *   普通交易 → InvalidTransaction；策略变更 → InvalidPolicyChange。
7	 * - RequestExpired 仅用于截止时间已过；PolicyConflict 仅用于执行时版本已漂移。
8	 * - NonceAlreadyUsedError 是既有重放防护的公开异常，策略变更沿用同一类型。
9	 */
10	
11	export class WalletError extends Error {
12	  constructor(message: string) {
13	    super(message);
14	    this.name = new.target.name;
15	  }
16	}
17	
18	/** 普通交易提交参数或签名不合法 */
19	export class InvalidTransaction extends WalletError {}
20	
21	/** 策略变更字段、版本、签名或 nonce 顺序不合法（不建任务、不消费 nonce、不改策略） */
22	export class InvalidPolicyChange extends WalletError {}
23	
24	/** 请求截止时间早于当前时间（提交时与执行时均可出现，不产生任务/不进入终态） */
25	export class RequestExpired extends WalletError {}
26	
27	/** 执行时发现任务绑定的策略版本已不是当前版本；任务进入既有失败终态 */
28	export class PolicyConflict extends WalletError {}
29	
30	/** nonce 已经被使用 —— 既有重放防护的公开异常，普通交易与策略变更共用 */
31	export class NonceAlreadyUsedError extends WalletError {
32	  readonly usedNonce: bigint;
33	  constructor(nonce: bigint) {
34	    super(`nonce already used: ${nonce}`);
35	    this.usedNonce = nonce;
36	  }
37	}
38	
39	/** 对不存在任务、终态任务重复执行等队列层面的非法操作 */
40	export class TaskNotFoundError extends WalletError {}
41	
42	export class InvalidQueueStateError extends WalletError {}
