308	export function signDigest(privateKey: Uint8Array, digest: Uint8Array): Buffer {
309	  const sk = Buffer.from(privateKey);
310	  if (sk.length !== 32) throw new Error('private key must be 32 bytes');
311	  if (digest.length !== 32) throw new Error('digest must be 32 bytes');
312	  const d = bytesToBigInt(sk);
313	  if (d <= 0n || d >= N) throw new Error('invalid private key');
314	  const e = bytesToBigInt(digest) % N;
315	  const nextK = rfc6979K(d, e);
316	
317	  for (let attempt = 0; attempt < 16; attempt++) {
318	    const k = nextK();
319	    if (k <= 0n || k >= N) continue;
320	    const R = toAffine(scalarMul(k, G))!;
321	    const r = R.x % N;
322	    if (r === 0n) continue;
323	    let s = modN(invMod(k, N) * modN(e + r * d));
324	    if (s === 0n) continue;
325	    let recoveryId = (R.x >= N ? 2 : 0) | Number(R.y & 1n);
326	    if (s > HALF_N) {
327	      s = N - s;
328	      recoveryId ^= 1;
329	    }
330	    const sig = Buffer.concat([to32(r), to32(s), Buffer.from([recoveryId])]);
331	    // 自检：恢复地址必须与私钥对应地址一致
332	    const selfAddress = addressFromPublicKey(publicKeyFromScalar(d));
333	    if (recoverAddress(digest, sig) === selfAddress) return sig;
334	  }
